-- quiz_seed.sql
-- 주식 1~5 학습 문서 기반 퀴즈 (5파트 × 20문항 = 100문항)

DROP TABLE IF EXISTS quiz_questions;

CREATE TABLE quiz_questions (
  day INTEGER NOT NULL,
  question_no INTEGER NOT NULL,
  source_doc TEXT NOT NULL,
  topic TEXT NOT NULL,
  question TEXT NOT NULL,
  choice_1 TEXT NOT NULL,
  choice_2 TEXT NOT NULL,
  choice_3 TEXT NOT NULL,
  choice_4 TEXT NOT NULL,
  answer INTEGER NOT NULL,
  explanation TEXT NOT NULL,
  PRIMARY KEY (day, question_no)
);

-- 주식 1: 병합 문서 03, 04, 05 → docs/03.md

-- 주식 2: 병합 문서 06, 07, 08 → docs/04.md

-- 주식 3: 병합 문서 09, 16 → docs/05.md

-- 주식 4: 병합 문서 10, 11, 12, 13 → docs/06.md

-- 주식 5: 병합 문서 14, 15 → docs/07.md

